INSERT INTO emails (id, folder_id, subject, sender, recipient, date, read, starred, body, in_reply_to, email_references, thread_id, message_id, raw_headers, cc, bcc) VALUES
('sam-10-e1', 'inbox', '[요청] 갤럭시 S25 Ultra Web Push Notification 디자인 의뢰', 'minjun.kim@samsung.com', 'bzengage@example.com', '2026-04-21T00:00:00.000Z', 1, 0, '<html><body>\n<p>비즈매트릭스 팀, 안녕하세요.</p>\n<p><strong>갤럭시 S25 Ultra</strong> 신제품 런칭을 위한 <strong>Web Push Notification</strong> 디자인 및 개발을 요청드립니다.</p>\n<h3>요청 사항:</h3>\n<ul>\n<li>메인 비주얼: 제품 이미지 중심의 클린한 디자인</li>\n<li>카피: "갤럭시 S25 Ultra — 당신의 일상을 바꾸다"</li>\n<li>CTA 버튼: "지금 예약하기" / "자세히 보기"</li>\n<li>반응형 대응 (PC/Mobile/Tablet)</li>\n</ul>\n<p>런칭 일정: <strong>5월 15일</strong></p>\n<p>1차 시안은 <strong>2026-04-21 이후 3영업일</strong> 내로 부탁드립니다.</p>\n<p>감사합니다.<br>김민준 드림<br>삼성전자 디지털마케팅팀</p>\n</body></html>', NULL, NULL, 'thread-samsung-10', 'msg-sam-10-e1', '[{"key":"from","value":"김민준 <minjun.kim@samsung.com>"},{"key":"to","value":"bzengage@example.com"},{"key":"subject","value":"[요청] 갤럭시 S25 Ultra Web Push Notification 디자인 의뢰"},{"key":"date","value":"2026-04-21T00:00:00.000Z"},{"key":"message-id","value":"<msg-sam-10-e1>"}]', NULL, NULL);
INSERT INTO emails (id, folder_id, subject, sender, recipient, date, read, starred, body, in_reply_to, email_references, thread_id, message_id, raw_headers, cc, bcc) VALUES
('sam-10-e2', 'sent', 'Re: [요청] 갤럭시 S25 Ultra Web Push Notification 디자인 의뢰', 'bzengage@example.com', 'minjun.kim@samsung.com', '2026-04-24T05:30:00.000Z', 1, 0, '<html><body>\n<p>김민준 님, 안녕하세요.</p>\n<p><strong>갤럭시 S25 Ultra</strong> Web Push Notification 1차 시안을 준비했습니다.</p>\n<h3>시안 개요:</h3>\n<ul>\n<li>메인 비주얼: 제품 3D 렌더링 이미지 + 그라데이션 배경</li>\n<li>카피 적용 완료</li>\n<li>PC/Mobile 반응형 레이아웃 적용</li>\n</ul>\n<p>첨부 파일에서 시안을 확인해 주시고, 피드백 부탁드립니다.</p>\n<p>감사합니다.<br>비즈매트릭스 팀</p>\n</body></html>', 'msg-sam-10-e1', '["msg-sam-10-e1"]', 'thread-samsung-10', 'msg-sam-10-e2', '[{"key":"from","value":"비즈매트릭스 <bzengage@example.com>"},{"key":"to","value":"minjun.kim@samsung.com"},{"key":"subject","value":"Re: [요청] 갤럭시 S25 Ultra Web Push Notification 디자인 의뢰"},{"key":"date","value":"2026-04-24T05:30:00.000Z"},{"key":"message-id","value":"<msg-sam-10-e2>"},{"key":"in-reply-to","value":"<msg-sam-10-e1>"},{"key":"references","value":"<msg-sam-10-e1>"}]', NULL, NULL);
INSERT INTO emails (id, folder_id, subject, sender, recipient, date, read, starred, body, in_reply_to, email_references, thread_id, message_id, raw_headers, cc, bcc) VALUES
('sam-10-e3', 'inbox', 'Re: [요청] 갤럭시 S25 Ultra Web Push Notification 디자인 의뢰 - 수정 요청', 'minjun.kim@samsung.com', 'bzengage@example.com', '2026-04-26T01:15:00.000Z', 1, 1, '<html><body>\n<p>비즈매트릭스 팀, 안녕하세요.</p>\n<p>1차 시안 확인했습니다. 전반적으로 좋습니다만, <strong>아래 수정 사항</strong>을 반영 부탁드립니다.</p>\n<h3>수정 요청 사항:</h3>\n<ol>\n<li>메인 비주얼 배경색을 <strong>코발트 블루</strong> 톤으로 변경</li>\n<li>CTA 버튼 색상을 삼성 브랜드 컬러로 조정</li>\n<li>모바일 버전에서 폰트 사이즈 1pt 업</li>\n<li>하단에 <strong>"자세한 사양 비교하기"</strong> 링크 추가</li>\n</ol>\n<p>2차 시안은 <strong>2026-04-26 이후 2영업일</strong> 내로 부탁드립니다.</p>\n<p>감사합니다.<br>김민준 드림</p>\n</body></html>', 'msg-sam-10-e2', '["msg-sam-10-e1","msg-sam-10-e2"]', 'thread-samsung-10', 'msg-sam-10-e3', '[{"key":"from","value":"김민준 <minjun.kim@samsung.com>"},{"key":"to","value":"bzengage@example.com"},{"key":"subject","value":"Re: [요청] 갤럭시 S25 Ultra Web Push Notification 디자인 의뢰 - 수정 요청"},{"key":"date","value":"2026-04-26T01:15:00.000Z"},{"key":"message-id","value":"<msg-sam-10-e3>"},{"key":"in-reply-to","value":"<msg-sam-10-e2>"},{"key":"references","value":"<msg-sam-10-e1> <msg-sam-10-e2>"}]', NULL, NULL);
INSERT INTO emails (id, folder_id, subject, sender, recipient, date, read, starred, body, in_reply_to, email_references, thread_id, message_id, raw_headers, cc, bcc) VALUES
('sam-10-e4', 'sent', 'Re: [요청] 갤럭시 S25 Ultra Web Push Notification 디자인 의뢰 - 2차 시안', 'bzengage@example.com', 'minjun.kim@samsung.com', '2026-04-28T07:00:00.000Z', 1, 0, '<html><body>\n<p>김민준 님, 안녕하세요.</p>\n<p>요청하신 수정 사항을 모두 반영한 <strong>2차 시안</strong>을 준비했습니다.</p>\n<h3>반영 내용:</h3>\n<ul>\n<li>배경색 → 코발트 블루 그라데이션 적용 완료</li>\n<li>CTA 버튼 색상 → 삼성 블루 #1428A0 적용</li>\n<li>모바일 폰트 사이즈 1pt 증가 완료</li>\n<li>"자세한 사양 비교하기" 링크 하단 추가 완료</li>\n</ul>\n<p>검토 부탁드립니다.</p>\n<p>감사합니다.<br>비즈매트릭스 팀</p>\n</body></html>', 'msg-sam-10-e3', '["msg-sam-10-e1","msg-sam-10-e2","msg-sam-10-e3"]', 'thread-samsung-10', 'msg-sam-10-e4', '[{"key":"from","value":"비즈매트릭스 <bzengage@example.com>"},{"key":"to","value":"minjun.kim@samsung.com"},{"key":"subject","value":"Re: [요청] 갤럭시 S25 Ultra Web Push Notification 디자인 의뢰 - 2차 시안"},{"key":"date","value":"2026-04-28T07:00:00.000Z"},{"key":"message-id","value":"<msg-sam-10-e4>"},{"key":"in-reply-to","value":"<msg-sam-10-e3>"},{"key":"references","value":"<msg-sam-10-e1> <msg-sam-10-e2> <msg-sam-10-e3>"}]', NULL, NULL);
INSERT INTO emails (id, folder_id, subject, sender, recipient, date, read, starred, body, in_reply_to, email_references, thread_id, message_id, raw_headers, cc, bcc) VALUES
('sam-10-e5', 'inbox', 'Re: [요청] 갤럭시 S25 Ultra Web Push Notification 디자인 의뢰 - 컨펌 및 최종 가이드', 'minjun.kim@samsung.com', 'bzengage@example.com', '2026-04-29T02:00:00.000Z', 0, 1, '<html><body>\n<p>비즈매트릭스 팀, 안녕하세요.</p>\n<p>2차 시안 확인했습니다. <strong>디자인 컨펌</strong>합니다.</p>\n<p>추가로 아래 <strong>최종 가이드</strong>를 확인 부탁드립니다:</p>\n<ul>\n<li>최종 파일 형식: PSD, AI, HTML</li>\n<li>배너 사이즈: 1920x600 (PC), 768x400 (Mobile), 320x250 (App)</li>\n<li>웹폰트: 삼성 One 폰트 사용</li>\n<li>이미지 해상도: 2x 이상</li>\n</ul>\n<p>최종 파일은 <strong>5월 10일</strong>까지 전달 부탁드립니다.</p>\n<p>감사합니다.<br>김민준 드림</p>\n</body></html>', 'msg-sam-10-e4', '["msg-sam-10-e1","msg-sam-10-e2","msg-sam-10-e3","msg-sam-10-e4"]', 'thread-samsung-10', 'msg-sam-10-e5', '[{"key":"from","value":"김민준 <minjun.kim@samsung.com>"},{"key":"to","value":"bzengage@example.com"},{"key":"subject","value":"Re: [요청] 갤럭시 S25 Ultra Web Push Notification 디자인 의뢰 - 컨펌 및 최종 가이드"},{"key":"date","value":"2026-04-29T02:00:00.000Z"},{"key":"message-id","value":"<msg-sam-10-e5>"},{"key":"in-reply-to","value":"<msg-sam-10-e4>"},{"key":"references","value":"<msg-sam-10-e1> <msg-sam-10-e2> <msg-sam-10-e3> <msg-sam-10-e4>"}]', NULL, NULL);
